def rellenar_inicio_reparacion(apps, schema_editor):
    """Equipos que ya están En reparación: la mejor fecha conocida es la de
    la alerta de reparación; si no hay, la de ingreso."""
    IngresoEquipo = apps.get_model('econotec', 'IngresoEquipo')
    for ingreso in IngresoEquipo.objects.filter(estado='en_reparacion').only(
        'pk', 'fecha_alerta_reparacion', 'fecha_ingreso',
    ):
        IngresoEquipo.objects.filter(pk=ingreso.pk).update(
            fecha_inicio_reparacion=ingreso.fecha_alerta_reparacion or ingreso.fecha_ingreso,
        )


